@SpringBootTest
class ContactViewTest extends SpringBrowserlessTest {

    @Autowired
    private MessageService messageService;

    @Test
    void initialStateIsEmptyAndSendIsEnabled() {
        ContactView view = navigate(ContactView.class);

        assertEquals("Contact", $(H1.class).first().getText());
        assertEquals("", $(TextField.class).withLabel("Name").first().getValue());
        assertEquals("", $(EmailField.class).first().getValue());
        assertEquals("", $(TextField.class).withLabel("Phone").first().getValue());
        assertEquals("", $(TextArea.class).first().getValue());
        assertTrue($(Button.class).withText("Send").first().isEnabled());
    }

    @Test
    void blankFormFailsValidationAndSendsNothing() {
        navigate(ContactView.class);
        int before = messageService.getAll().size();

        test($(Button.class).withText("Send").first()).click();

        TextField name = $(TextField.class).withLabel("Name").first();
        EmailField email = $(EmailField.class).first();
        TextArea message = $(TextArea.class).first();

        assertTrue(name.isInvalid());
        assertEquals("Name is required", name.getErrorMessage());
        assertTrue(email.isInvalid());
        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
        assertTrue(message.isInvalid());
        assertEquals("Message is required", message.getErrorMessage());

        assertEquals(before, messageService.getAll().size());
    }

    @Test
    void invalidEmailIsRejectedEvenWithPhone() {
        navigate(ContactView.class);

        test($(TextField.class).withLabel("Name").first()).setValue("Ann");
        test($(EmailField.class).first()).setValue("not-an-email");
        test($(TextField.class).withLabel("Phone").first()).setValue("12345");
        test($(TextArea.class).first()).setValue("Hello there");

        test($(Button.class).withText("Send").first()).click();

        EmailField email = $(EmailField.class).first();
        assertTrue(email.isInvalid());
        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
    }

